def ask_perplexity(api_key, question, idempotency_key=None, model=None, search_recency_filter=None, temperature=None, max_tokens=None, top_p=None, return_citations=None, return_provider_payload=None, **_extra):
    import json, os, datetime, time, base64, hashlib, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0074000" if __import__("os").path.isdir("./environment_mix/0074000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    period_ym = now[:7]

    def _log(workspace_id, api_key_id, status, tool_name, input_obj, request_id=None, error_code=None, error_message=None, latency_ms=None, est_in=0, est_out=0):
        # Append-only usage_ledger is for quota, not request logs. The "request log" is perplexity_requests itself.
        # Still, ensure the request record exists/updated for every call path that creates/returns one.
        return

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _make_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    # ----------------- validate inputs -----------------
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if not isinstance(question, str) or not question.strip():
        return _err("VALIDATION_ERROR", "question must be a non-empty string", field="question")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided", field="idempotency_key")
    if model is not None and not isinstance(model, str):
        return _err("VALIDATION_ERROR", "model must be a string when provided", field="model")
    if search_recency_filter is not None:
        if not isinstance(search_recency_filter, str):
            return _err("VALIDATION_ERROR", "search_recency_filter must be a string when provided", field="search_recency_filter")
        if search_recency_filter not in ["hour", "day", "week", "month", "year", "all"]:
            return _err("VALIDATION_ERROR", "search_recency_filter must be one of: hour, day, week, month, year, all", field="search_recency_filter")
    if temperature is not None and not isinstance(temperature, (int, float)):
        return _err("VALIDATION_ERROR", "temperature must be a number when provided", field="temperature")
    if top_p is not None and not isinstance(top_p, (int, float)):
        return _err("VALIDATION_ERROR", "top_p must be a number when provided", field="top_p")
    if max_tokens is not None:
        if not isinstance(max_tokens, int):
            return _err("VALIDATION_ERROR", "max_tokens must be an integer when provided", field="max_tokens")
        if max_tokens < 1:
            return _err("VALIDATION_ERROR", "max_tokens must be >= 1", field="max_tokens")
    if return_citations is not None and not isinstance(return_citations, bool):
        return _err("VALIDATION_ERROR", "return_citations must be a boolean when provided", field="return_citations")
    if return_provider_payload is not None and not isinstance(return_provider_payload, bool):
        return _err("VALIDATION_ERROR", "return_provider_payload must be a boolean when provided", field="return_provider_payload")

    # ----------------- authenticate api_key -----------------
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    requests = _load("perplexity_requests.json")
    answers = _load("perplexity_answers.json")
    ledger = _load("usage_ledger.json")

    # Authenticate by matching client-visible value OR id, never by hash check.
    key_row = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key")

    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is revoked", reason="FORBIDDEN")

    ws = None
    ws_id = key_row.get("workspace_id")
    for w in workspaces:
        if w.get("id") == ws_id:
            ws = w
            break
    if not ws:
        return _err("UNAUTHORIZED", "API key workspace not found")

    if ws.get("status") != "active":
        # reject before creating a running request
        return _err("UNAUTHORIZED", f"Workspace is not active (status={ws.get('status')})", reason="FORBIDDEN")

    # Update last_used_at only on successful authenticated calls (this call is authenticated if we proceed past here).
    # We'll update at end upon success; but the tool may be rejected for quota. That's still authenticated; rule says only updated on successful authenticated calls.
    # Interpret "successful" as non-error response.
    update_last_used = True

    # ----------------- idempotency: return existing request -----------------
    if idempotency_key is not None:
        existing = None
        for r in requests:
            if r.get("workspace_id") == ws_id and r.get("idempotency_key") == idempotency_key:
                existing = r
                break
        if existing:
            # Find answer if any
            ans = None
            for a in answers:
                if a.get("request_id") == existing.get("id"):
                    ans = a
                    break
            # Build response
            resp = {
                "request": dict(existing),
                "answer": dict(ans) if ans else None,
            }
            # redact provider_payload depending on flag
            if resp["answer"] and not (return_provider_payload is True):
                resp["answer"] = dict(resp["answer"])
                resp["answer"]["provider_payload"] = {}  # redacted
            if resp["answer"] and not (return_citations is True):
                resp["answer"] = dict(resp["answer"])
                resp["answer"]["citations"] = []
            # update last_used_at on successful return
            if update_last_used:
                key_row["last_used_at"] = now
                key_row["updated_at"] = now
                _save("api_keys.json", api_keys)
            return resp

    # ----------------- quota enforcement (before upstream) -----------------
    # Compute current period usage for workspace
    req_used = 0
    tokens_used = 0
    for e in ledger:
        if e.get("workspace_id") == ws_id and e.get("period_ym") == period_ym:
            if e.get("event_type") == "request":
                req_used += int(e.get("quantity") or 0)
            elif e.get("event_type") in ("tokens_in", "tokens_out"):
                tokens_used += int(e.get("quantity") or 0)

    monthly_request_quota = ws.get("monthly_request_quota")
    monthly_token_quota = ws.get("monthly_token_quota")
    try:
        monthly_request_quota = int(monthly_request_quota)
        monthly_token_quota = int(monthly_token_quota)
    except Exception:
        return _err("VALIDATION_ERROR", "Workspace quotas are misconfigured")

    if monthly_request_quota < 0 or monthly_token_quota < 0:
        return _err("VALIDATION_ERROR", "Workspace quotas are misconfigured (negative)")

    # Estimate tokens in/out (simple heuristic)
    est_in = max(0, len(question.strip()) // 4)
    est_out = 0
    if isinstance(max_tokens, int):
        est_out = max_tokens
    else:
        est_out = min(512, max(64, est_in // 2))

    if req_used + 1 > monthly_request_quota:
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded", period_ym=period_ym, used=req_used, quota=monthly_request_quota)
    if tokens_used + est_in + est_out > monthly_token_quota:
        return _err("QUOTA_EXCEEDED", "Monthly token quota exceeded", period_ym=period_ym, used=tokens_used, quota=monthly_token_quota, estimated_additional=est_in + est_out)

    # ----------------- create request row (queued -> running -> succeeded) -----------------
    req_id = _make_id("pplxreq")
    req_row = {
        "id": req_id,
        "workspace_id": ws_id,
        "api_key_id": key_row.get("id"),
        "tool_name": "ask_perplexity",
        "input": {},  # per rule
        "idempotency_key": idempotency_key,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "remote_request_id": None,
        "latency_ms": None,
        "estimated_tokens_in": int(est_in),
        "estimated_tokens_out": 0,
        "created_at": now,
        "updated_at": now,
    }

    # enforce uniqueness(workspace_id, idempotency_key) where not null (race-safe best effort in file store)
    if idempotency_key is not None:
        for r in requests:
            if r.get("workspace_id") == ws_id and r.get("idempotency_key") == idempotency_key:
                # Another writer already created it: return it
                existing = r
                ans = None
                for a in answers:
                    if a.get("request_id") == existing.get("id"):
                        ans = a
                        break
                resp = {"request": dict(existing), "answer": dict(ans) if ans else None}
                if resp["answer"] and not (return_provider_payload is True):
                    resp["answer"] = dict(resp["answer"])
                    resp["answer"]["provider_payload"] = {}
                if resp["answer"] and not (return_citations is True):
                    resp["answer"] = dict(resp["answer"])
                    resp["answer"]["citations"] = []
                key_row["last_used_at"] = now
                key_row["updated_at"] = now
                _save("api_keys.json", api_keys)
                return resp

    requests.append(req_row)
    _save("perplexity_requests.json", requests)

    # Transition to running (legal)
    for r in requests:
        if r.get("id") == req_id:
            r["status"] = "running"
            r["updated_at"] = now
            break
    _save("perplexity_requests.json", requests)

    # ----------------- "upstream" execution (offline simulated) -----------------
    # Deterministic pseudo-answer based on question, model.
    start_exec = time.time()
    remote_id = "remote_" + hashlib.sha256((question + "|" + (model or "")).encode("utf-8")).hexdigest()[:24]
    answer_text = f"Simulated Perplexity answer.\n\nQuestion: {question.strip()}\nModel: {model or 'default'}\n\nThis server runs offline and records requests/answers locally."
    citations = []
    if return_citations is True:
        citations = [{
            "url": "https://example.com/offline-simulation",
            "title": "Offline Simulation",
            "snippet": "This is a locally simulated response; no live web lookup was performed."
        }]
    provider_payload = {
        "provider": "perplexity",
        "mode": "offline_simulation",
        "model": model or "default",
        "search_recency_filter": search_recency_filter,
        "temperature": temperature,
        "top_p": top_p,
        "max_tokens": max_tokens,
        "remote_request_id": remote_id,
    }
    end_exec = time.time()
    latency_ms = int(round((end_exec - start_exec) * 1000))

    # Transition running -> succeeded (legal) and write completion fields
    updated_now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for r in requests:
        if r.get("id") == req_id:
            r["status"] = "succeeded"
            r["remote_request_id"] = remote_id
            r["latency_ms"] = max(0, latency_ms)
            r["estimated_tokens_out"] = int(est_out)
            r["updated_at"] = updated_now
            break
    _save("perplexity_requests.json", requests)

    # Create answer row on completion; unique(request_id)
    existing_answer = None
    for a in answers:
        if a.get("request_id") == req_id:
            existing_answer = a
            break
    if existing_answer is None:
        ans_id = _make_id("pplxans")
        ans_row = {
            "id": ans_id,
            "request_id": req_id,
            "status": "final",
            "answer_text": answer_text,
            "citations": citations if (return_citations is True) else [],
            "provider_payload": provider_payload if (return_provider_payload is True) else {},
            "created_at": updated_now,
            "updated_at": updated_now,
        }
        answers.append(ans_row)
        _save("perplexity_answers.json", answers)
    else:
        # Terminal states cannot be semantically modified; but if it exists, keep it as-is.
        pass

    # Write usage_ledger exactly three entries; unique(request_id,event_type)
    def _ledger_upsert(event_type, quantity):
        nonlocal ledger
        for e in ledger:
            if e.get("request_id") == req_id and e.get("event_type") == event_type:
                return  # idempotent
        ledger.append({
            "id": _make_id("usage"),
            "workspace_id": ws_id,
            "api_key_id": key_row.get("id"),
            "request_id": req_id,
            "event_type": event_type,
            "quantity": int(max(0, quantity)),
            "period_ym": period_ym,
            "created_at": updated_now,
            "updated_at": updated_now,
        })

    _ledger_upsert("request", 1)
    _ledger_upsert("tokens_in", int(est_in))
    _ledger_upsert("tokens_out", int(est_out))
    _save("usage_ledger.json", ledger)

    # Update last_used_at on successful call
    key_row["last_used_at"] = updated_now
    key_row["updated_at"] = updated_now
    _save("api_keys.json", api_keys)

    # Return recorded session
    final_req = None
    for r in requests:
        if r.get("id") == req_id:
            final_req = r
            break
    final_ans = None
    for a in answers:
        if a.get("request_id") == req_id:
            final_ans = a
            break

    if final_req is None:
        return _err("NOT_FOUND", "Request not found after creation (datastore error)")

    out_answer = dict(final_ans) if final_ans else None
    if out_answer and not (return_provider_payload is True):
        out_answer["provider_payload"] = {}
    if out_answer and not (return_citations is True):
        out_answer["citations"] = []

    return {
        "request": dict(final_req),
        "answer": out_answer
    }

def get_me(api_key, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0074000" if __import__("os").path.isdir("./environment_mix/0074000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    period_ym = now[:7]

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    ledger = _load("usage_ledger.json")

    key_row = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key")

    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is revoked", reason="FORBIDDEN")

    ws = None
    for w in workspaces:
        if w.get("id") == key_row.get("workspace_id"):
            ws = w
            break
    if not ws:
        return _err("UNAUTHORIZED", "API key workspace not found")

    # Compute current period usage
    req_used = 0
    tokens_used = 0
    for e in ledger:
        if e.get("workspace_id") == ws.get("id") and e.get("period_ym") == period_ym:
            if e.get("event_type") == "request":
                req_used += int(e.get("quantity") or 0)
            elif e.get("event_type") in ("tokens_in", "tokens_out"):
                tokens_used += int(e.get("quantity") or 0)

    # Successful authenticated call: update last_used_at
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    _save("api_keys.json", api_keys)

    return {
        "workspace": {
            "id": ws.get("id"),
            "name": ws.get("name"),
            "status": ws.get("status"),
            "monthly_request_quota": ws.get("monthly_request_quota"),
            "monthly_token_quota": ws.get("monthly_token_quota"),
            "created_at": ws.get("created_at"),
            "updated_at": ws.get("updated_at"),
        },
        "api_key": {
            "id": key_row.get("id"),
            "workspace_id": key_row.get("workspace_id"),
            "label": key_row.get("label"),
            "status": key_row.get("status"),
            "last_used_at": key_row.get("last_used_at"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
        },
        "scopes": ["perplexity.ask", "perplexity.read"],
        "current_period": {
            "period_ym": period_ym,
            "requests_used": req_used,
            "requests_quota": int(ws.get("monthly_request_quota") or 0),
            "tokens_used": tokens_used,
            "tokens_quota": int(ws.get("monthly_token_quota") or 0),
        }
    }

def list_perplexity_requests(api_key, status=None, idempotency_key=None, remote_request_id=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0074000" if __import__("os").path.isdir("./environment_mix/0074000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string when provided", field="status")
        if status not in ["queued", "running", "succeeded", "failed", "cancelled"]:
            return _err("VALIDATION_ERROR", "status must be one of queued,running,succeeded,failed,cancelled", field="status")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided", field="idempotency_key")
    if remote_request_id is not None and (not isinstance(remote_request_id, str) or not remote_request_id.strip()):
        return _err("VALIDATION_ERROR", "remote_request_id must be a non-empty string when provided", field="remote_request_id")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")

    ca = _parse_rfc3339(created_after)
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be an RFC3339 timestamp", field="created_after")
    cb = _parse_rfc3339(created_before)
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be an RFC3339 timestamp", field="created_before")

    api_keys = _load("api_keys.json")
    requests = _load("perplexity_requests.json")

    key_row = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is revoked", reason="FORBIDDEN")

    ws_id = key_row.get("workspace_id")

    # decode cursor: base64 of request created_at + "|" + id
    start_after = None
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            parts = raw.split("|", 1)
            if len(parts) == 2:
                start_after = (parts[0], parts[1])
            else:
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    # Filter
    rows = []
    for r in requests:
        if r.get("workspace_id") != ws_id:
            continue
        if r.get("tool_name") != "ask_perplexity":
            continue
        if status is not None and r.get("status") != status:
            continue
        if idempotency_key is not None and r.get("idempotency_key") != idempotency_key:
            continue
        if remote_request_id is not None and r.get("remote_request_id") != remote_request_id:
            continue
        r_created = _parse_rfc3339(r.get("created_at")) if isinstance(r.get("created_at"), str) else None
        if ca is not None and r_created is not None and r_created < ca:
            continue
        if cb is not None and r_created is not None and r_created >= cb:
            continue
        rows.append(r)

    # Sort newest first by created_at then id
    def _k(r):
        return (r.get("created_at") or "", r.get("id") or "")
    rows.sort(key=_k, reverse=True)

    # Apply cursor (start_after means return items strictly older than that tuple in this sort)
    if start_after:
        filtered = []
        for r in rows:
            tup = (r.get("created_at") or "", r.get("id") or "")
            if tup < start_after:  # since sorted desc, we want those "less than" the boundary
                filtered.append(r)
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = total > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = f"{last.get('created_at') or ''}|{last.get('id') or ''}"
        next_cursor = base64.urlsafe_b64encode(payload.encode("utf-8")).decode("utf-8")

    # Successful authenticated call: update last_used_at
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    _save("api_keys.json", api_keys)

    return {
        "data": [dict(r) for r in page],
        "pagination": {
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_perplexity_request(api_key, request_id, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0074000" if __import__("os").path.isdir("./environment_mix/0074000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if not isinstance(request_id, str) or not request_id.strip():
        return _err("VALIDATION_ERROR", "request_id must be a non-empty string", field="request_id")

    api_keys = _load("api_keys.json")
    requests = _load("perplexity_requests.json")
    answers = _load("perplexity_answers.json")

    key_row = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is revoked", reason="FORBIDDEN")

    ws_id = key_row.get("workspace_id")

    req = None
    for r in requests:
        if r.get("id") == request_id and r.get("workspace_id") == ws_id:
            req = r
            break
    if not req:
        return _err("NOT_FOUND", "Request not found")

    ans = None
    for a in answers:
        if a.get("request_id") == request_id:
            ans = a
            break

    # Successful authenticated call: update last_used_at
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    _save("api_keys.json", api_keys)

    return {
        "request": dict(req),
        "answer": dict(ans) if ans else None
    }

def cancel_perplexity_request(api_key, request_id, reason=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0074000" if __import__("os").path.isdir("./environment_mix/0074000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _coerce_list(x):
        return x if isinstance(x, list) else []

    def _period_ym(dt):
        return dt.strftime("%Y-%m")

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:26]}"

    # ---- Validate inputs ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(request_id, str) or not request_id.strip():
        return _err("VALIDATION_ERROR", "request_id must be a non-empty string")
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "reason must be a string if provided")

    # ---- Load datastore ----
    workspaces = _coerce_list(_load("workspaces.json"))
    api_keys = _coerce_list(_load("api_keys.json"))
    requests = _coerce_list(_load("perplexity_requests.json"))
    answers = _coerce_list(_load("perplexity_answers.json"))
    usage = _coerce_list(_load("usage_ledger.json"))

    # ---- Resolve request ----
    req = None
    for r in requests:
        if isinstance(r, dict) and r.get("id") == request_id:
            req = r
            break
    if req is None:
        return _err("NOT_FOUND", "Perplexity request not found", request_id=request_id)

    # ---- Authenticate API key (match by id or client-visible value; never key_hash) ----
    # In this datastore, the only client-visible value available is typically the key id itself.
    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key:
            key_row = k
            break
        # Some vendors accept either "id" or a separately issued plaintext key; this store does not retain it.
        # We intentionally do not attempt to compare against key_hash.
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is revoked", rule="api_keys with status='revoked' cannot be used")

    # ---- Authorize against workspace scope (must match request.workspace_id) ----
    ws_id = key_row.get("workspace_id")
    if not isinstance(ws_id, str) or not ws_id:
        return _err("UNAUTHORIZED", "API key is not associated with a workspace")
    req_ws_id = req.get("workspace_id")
    if req_ws_id != ws_id:
        # This must be a real rule; however, do not reject a well-formed call due to hash checks.
        return _err(
            "UNAUTHORIZED",
            "API key is not authorized to operate on this request (workspace mismatch).",
            rule="Requests are scoped to a workspace; API keys may only operate on requests in their own workspace.",
            workspace_id=ws_id,
            request_workspace_id=req_ws_id,
        )

    # ---- Workspace lifecycle gate (suspended/deleted cannot execute; cancel is allowed) ----
    ws_row = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == ws_id:
            ws_row = w
            break
    if ws_row is None:
        return _err("NOT_FOUND", "Workspace not found for API key", workspace_id=ws_id)

    # ---- Enforce lifecycle transition: queued/running -> cancelled only ----
    cur = req.get("status")
    allowed = {"queued": {"running", "cancelled"}, "running": {"succeeded", "failed", "cancelled"}, "succeeded": set(), "failed": set(), "cancelled": set()}
    if cur not in allowed:
        return _err("VALIDATION_ERROR", "Invalid request status value", status=cur)

    if "cancelled" not in allowed.get(cur, set()):
        return _err(
            "CONFLICT",
            "Request is already in a terminal state and cannot be cancelled.",
            rule="Requests may only transition according to the defined lifecycle; terminal states cannot be modified.",
            status=cur,
        )

    # ---- Apply update (no success without effect) ----
    req["status"] = "cancelled"
    # keep error_code/message null; reason is audit-only. There is no schema field for reason, so store in input.
    # input is defined as raw params JSON; for this tool it's {}, but we can append audit metadata safely there
    # without affecting ask_perplexity semantics? It's still an object. We'll preserve existing input and add cancellation.
    inp = req.get("input")
    if not isinstance(inp, dict):
        inp = {}
    inp = dict(inp)
    if reason is not None:
        inp["_cancellation_reason"] = reason
    inp["_cancelled_at"] = now
    req["input"] = inp
    req["updated_at"] = now

    # ---- Persist ----
    _save("perplexity_requests.json", requests)

    # ---- Observable service dynamics: record call in usage_ledger as a request audit event (quantity=0) ----
    # Schema restricts event_type to request/tokens_in/tokens_out and quantity>=0 with unique(request_id,event_type).
    # To avoid violating uniqueness for real ask_perplexity usage entries, only create an audit record when none exists
    # for this request+event_type='request' AND quantity=0. If a real usage row exists, we do not add another.
    # This ensures "every call records itself" without corrupting metering.
    existing_req_event = False
    for u in usage:
        if isinstance(u, dict) and u.get("request_id") == request_id and u.get("event_type") == "request":
            existing_req_event = True
            break
    if not existing_req_event:
        # Add a zero-quantity audit marker; does not affect quota sums.
        usage.append({
            "id": _gen_id("pplx_use"),
            "workspace_id": ws_id,
            "api_key_id": key_row.get("id"),
            "request_id": request_id,
            "event_type": "request",
            "quantity": 0,
            "period_ym": _period_ym(now_dt),
            "created_at": now,
            "updated_at": now,
        })
        _save("usage_ledger.json", usage)

    # ---- Update key last_used_at (successful authenticated call) ----
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    _save("api_keys.json", api_keys)

    latency_ms = int(max(0, (time.time() - t0) * 1000))

    return {
        "request": req,
        "meta": {
            "cancelled": True,
            "latency_ms": latency_ms,
        },
    }

def list_usage_ledger(api_key, period_ym=None, event_type=None, request_id=None, api_key_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0074000" if __import__("os").path.isdir("./environment_mix/0074000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if period_ym is not None:
        if not isinstance(period_ym, str) or not re.fullmatch(r"\d{4}-\d{2}", period_ym):
            return _err("VALIDATION_ERROR", "period_ym must be in YYYY-MM format")
    if event_type is not None:
        if event_type not in ("request", "tokens_in", "tokens_out"):
            return _err("VALIDATION_ERROR", "event_type must be one of: request, tokens_in, tokens_out")
    if request_id is not None and (not isinstance(request_id, str) or not request_id.strip()):
        return _err("VALIDATION_ERROR", "request_id must be a non-empty string if provided")
    if api_key_id is not None and (not isinstance(api_key_id, str) or not api_key_id.strip()):
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string if provided")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string if provided")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    usage = _load("usage_ledger.json")
    requests = _load("perplexity_requests.json")

    # Authenticate: api_key must match an api_keys.id
    key_row = None
    for k in api_keys:
        if k.get("id") == api_key:
            key_row = k
            break
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is revoked")

    ws = None
    for w in workspaces:
        if w.get("id") == key_row.get("workspace_id"):
            ws = w
            break
    if not ws:
        return _err("UNAUTHORIZED", "Workspace not found for API key")

    # Pagination cursor decode: base64url of {"offset": int}
    offset = 0
    if cursor is not None:
        try:
            raw = cursor.encode("utf-8")
            pad = b"=" * ((4 - (len(raw) % 4)) % 4)
            decoded = base64.urlsafe_b64decode(raw + pad).decode("utf-8")
            obj = json.loads(decoded)
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor")
            offset = obj["offset"]
        except (ValueError, json.JSONDecodeError):
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # Filter
    rows = [r for r in usage if r.get("workspace_id") == ws.get("id")]
    if period_ym is not None:
        rows = [r for r in rows if r.get("period_ym") == period_ym]
    if event_type is not None:
        rows = [r for r in rows if r.get("event_type") == event_type]
    if request_id is not None:
        rows = [r for r in rows if r.get("request_id") == request_id]
    if api_key_id is not None:
        rows = [r for r in rows if r.get("api_key_id") == api_key_id]

    # Sort newest first by created_at then id for stability
    def _ts(x):
        v = x.get("created_at")
        return v if isinstance(v, str) else ""
    rows.sort(key=lambda r: (_ts(r), r.get("id", "")), reverse=True)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Update last_used_at on successful authenticated call
    now2 = now
    key_row = dict(key_row)
    key_row["last_used_at"] = now2
    key_row["updated_at"] = now2
    for i, k in enumerate(api_keys):
        if k.get("id") == key_row.get("id"):
            api_keys[i] = key_row
            break

    # Log the call into perplexity_requests as system request-log row
    log_id = "pr_" + uuid.uuid4().hex
    log_row = {
        "id": log_id,
        "workspace_id": ws.get("id"),
        "api_key_id": key_row.get("id"),
        "tool_name": "ask_perplexity",
        "input": {
            "operation": "list_usage_ledger",
            "filters": {
                "period_ym": period_ym,
                "event_type": event_type,
                "request_id": request_id,
                "api_key_id": api_key_id
            },
            "limit": limit,
            "cursor": cursor
        },
        "idempotency_key": None,
        "status": "succeeded",
        "error_code": None,
        "error_message": None,
        "remote_request_id": None,
        "latency_ms": max(0, int((time.time() - t0) * 1000)),
        "estimated_tokens_in": 0,
        "estimated_tokens_out": 0,
        "created_at": now2,
        "updated_at": now2
    }
    requests.append(log_row)

    _save("api_keys.json", api_keys)
    _save("perplexity_requests.json", requests)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def create_api_key(api_key, label=None, **_extra):
    import json, os, datetime, time, uuid, secrets, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0074000" if __import__("os").path.isdir("./environment_mix/0074000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if label is not None and not isinstance(label, str):
        return _err("VALIDATION_ERROR", "label must be a string if provided")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    requests = _load("perplexity_requests.json")

    # Authenticate using provided api_key as api_keys.id
    caller_key = None
    for k in api_keys:
        if k.get("id") == api_key:
            caller_key = k
            break
    if not caller_key:
        return _err("UNAUTHORIZED", "Invalid API key")
    if caller_key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is revoked")

    ws = None
    for w in workspaces:
        if w.get("id") == caller_key.get("workspace_id"):
            ws = w
            break
    if not ws:
        return _err("UNAUTHORIZED", "Workspace not found for API key")

    if ws.get("status") in ("suspended", "deleted"):
        return _err("UNAUTHORIZED", "Workspace is not allowed to create API keys in its current status")

    # Create raw key (returned once) and store only hash
    raw_key = "pplxsk_" + secrets.token_urlsafe(32)
    key_hash = hashlib.sha256(raw_key.encode("utf-8")).hexdigest()

    # Enforce unique(workspace_id, key_hash)
    for k in api_keys:
        if k.get("workspace_id") == ws.get("id") and k.get("key_hash") == key_hash:
            # extremely unlikely; regenerate once
            raw_key = "pplxsk_" + secrets.token_urlsafe(32)
            key_hash = hashlib.sha256(raw_key.encode("utf-8")).hexdigest()
            break
    for k in api_keys:
        if k.get("workspace_id") == ws.get("id") and k.get("key_hash") == key_hash:
            return _err("CONFLICT", "Failed to generate a unique API key hash; retry")

    new_id = "key_" + uuid.uuid4().hex
    new_row = {
        "id": new_id,
        "workspace_id": ws.get("id"),
        "key_hash": key_hash,
        "label": label,
        "status": "active",
        "last_used_at": None,
        "created_at": now,
        "updated_at": now
    }

    api_keys.append(new_row)

    # Update last_used_at on successful authenticated call (caller key)
    caller_key2 = dict(caller_key)
    caller_key2["last_used_at"] = now
    caller_key2["updated_at"] = now
    for i, k in enumerate(api_keys):
        if k.get("id") == caller_key2.get("id"):
            api_keys[i] = caller_key2
            break

    # Log the call into perplexity_requests as system request-log row
    log_id = "pr_" + uuid.uuid4().hex
    log_row = {
        "id": log_id,
        "workspace_id": ws.get("id"),
        "api_key_id": caller_key2.get("id"),
        "tool_name": "ask_perplexity",
        "input": {"operation": "create_api_key", "label": label},
        "idempotency_key": None,
        "status": "succeeded",
        "error_code": None,
        "error_message": None,
        "remote_request_id": None,
        "latency_ms": max(0, int((time.time() - t0) * 1000)),
        "estimated_tokens_in": 0,
        "estimated_tokens_out": 0,
        "created_at": now,
        "updated_at": now
    }
    requests.append(log_row)

    _save("api_keys.json", api_keys)
    _save("perplexity_requests.json", requests)

    return {
        "api_key": {
            "id": new_row["id"],
            "workspace_id": new_row["workspace_id"],
            "label": new_row["label"],
            "status": new_row["status"],
            "created_at": new_row["created_at"]
        },
        "raw_key": raw_key
    }
